  function toggleLogbookVisibleFor(role: string, checked: boolean) {
    setLogbookVisibleFor((currentRoles) =>
      checked ? [...new Set([...currentRoles, role])] : currentRoles.filter((item) => item !== role)
    );
  }

  function formatLogbookFileSize(bytes: number) {
    return `${Math.round(bytes / 1024 / 1024)} MB`;
  }

  function getLogbookFileExtension(fileName: string) {
    return fileName.match(/\.[^.]+$/)?.[0]?.toLowerCase() || "";
  }

  function getLogbookAttachmentBytes(attachment: LogbookAttachment) {
    const dataUrlPayload = attachment.dataUrl?.split(",")[1] || "";
    const estimatedDataUrlBytes = dataUrlPayload ? Math.ceil((dataUrlPayload.length * 3) / 4) : 0;
    return Math.max(attachment.size || 0, estimatedDataUrlBytes);
  }

  function getLogbookFileValidationMessage(file: File, type: "Bild" | "Dokument") {
    if (file.size > MAX_LOGBOOK_ATTACHMENT_BYTES) {
      return `"${file.name}" ist zu gross. Erlaubt sind maximal ${formatLogbookFileSize(
        MAX_LOGBOOK_ATTACHMENT_BYTES
      )} pro Datei.`;
    }

    const mimeType = file.type.toLowerCase();
    const extension = getLogbookFileExtension(file.name);
    const isImage =
      ALLOWED_LOGBOOK_IMAGE_MIME_TYPES.has(mimeType) ||
      (!mimeType && ALLOWED_LOGBOOK_IMAGE_EXTENSIONS.has(extension)) ||
      ALLOWED_LOGBOOK_IMAGE_EXTENSIONS.has(extension);

    if (type === "Bild") {
      return isImage ? "" : `"${file.name}" ist kein erlaubtes Bildformat.`;
    }

    const isDocument =
      ALLOWED_LOGBOOK_DOCUMENT_MIME_TYPES.has(mimeType) ||
      (!mimeType && ALLOWED_LOGBOOK_DOCUMENT_EXTENSIONS.has(extension)) ||
      ALLOWED_LOGBOOK_DOCUMENT_EXTENSIONS.has(extension);

    return isImage || isDocument ? "" : `"${file.name}" ist kein erlaubter Dokumenttyp.`;
  }

  function getLogbookAttachmentsValidationMessage(attachments: LogbookAttachment[]) {
    const totalBytes = attachments.reduce((sum, attachment) => sum + getLogbookAttachmentBytes(attachment), 0);
    const oversizedAttachment = attachments.find(
      (attachment) => getLogbookAttachmentBytes(attachment) > MAX_LOGBOOK_ATTACHMENT_BYTES
    );

    if (oversizedAttachment) {
      return `"${oversizedAttachment.name}" ist zu gross. Erlaubt sind maximal ${formatLogbookFileSize(
        MAX_LOGBOOK_ATTACHMENT_BYTES
      )} pro Datei.`;
    }

    if (totalBytes > MAX_LOGBOOK_ENTRY_ATTACHMENT_BYTES) {
      return `Die Anhaenge sind zusammen zu gross. Erlaubt sind maximal ${formatLogbookFileSize(
        MAX_LOGBOOK_ENTRY_ATTACHMENT_BYTES
      )} pro Eintrag.`;
    }

    return "";
  }

  function readLogbookAttachment(file: File, type: "Bild" | "Dokument") {
    return new Promise<LogbookAttachment>((resolve, reject) => {
      const validationMessage = getLogbookFileValidationMessage(file, type);
      if (validationMessage) {
        reject(new Error(validationMessage));
        return;
      }

      const reader = new FileReader();

      reader.onerror = () => reject(new Error("Anhang konnte nicht gelesen werden."));
      reader.onload = () =>
        resolve({
          name: file.name,
          type,
          mimeType: file.type,
          size: file.size,
          dataUrl: String(reader.result ?? ""),
        });
      reader.readAsDataURL(file);
    });
  }

  function readProjectImageAttachment(file: File, displayNameBase?: string) {
    return new Promise<LogbookAttachment>((resolve, reject) => {
      const validationMessage = getLogbookFileValidationMessage(file, "Bild");
      if (validationMessage) {
        reject(new Error(validationMessage));
        return;
      }

      const reader = new FileReader();
      const originalExtension = file.name.match(/\.[^.]+$/)?.[0]?.toLowerCase() || ".jpg";
      const safeOriginalExtension = [".jpg", ".jpeg", ".png", ".webp"].includes(originalExtension)
        ? originalExtension.replace(".jpeg", ".jpg")
        : ".jpg";
      const safeNameBase = displayNameBase ? sanitizeFileNamePart(displayNameBase) : file.name.replace(/\.[^.]+$/, "");

      reader.onerror = () => reject(new Error(`Bild "${file.name}" konnte nicht gelesen werden.`));
      reader.onload = () => {
        const originalDataUrl = String(reader.result ?? "");
        const image = new Image();

        image.onerror = () =>
          reject(new Error(`Bild "${file.name}" konnte nicht verarbeitet werden.`));
        image.onload = () => {
          const maxEdge = 1600;
          const scale = Math.min(1, maxEdge / Math.max(image.width, image.height));
          const width = Math.max(1, Math.round(image.width * scale));
          const height = Math.max(1, Math.round(image.height * scale));

          if (!scale || (scale >= 1 && file.size <= 700_000)) {
            resolve({
              name: `${safeNameBase}${safeOriginalExtension}`,
              type: "Bild",
              mimeType: file.type || "image/jpeg",
              size: file.size,
              dataUrl: originalDataUrl,
            });
            return;
          }

          const canvas = document.createElement("canvas");
          canvas.width = width;
          canvas.height = height;
          const context = canvas.getContext("2d");

          if (!context) {
            reject(new Error(`Bild "${file.name}" konnte nicht vorbereitet werden.`));
            return;
          }

          context.drawImage(image, 0, 0, width, height);
          const dataUrl = canvas.toDataURL("image/jpeg", 0.82);
          const base64Length = dataUrl.split(",")[1]?.length ?? 0;
          const estimatedSize = Math.round((base64Length * 3) / 4);

          resolve({
            name: `${safeNameBase}.jpg`,
            type: "Bild",
            mimeType: "image/jpeg",
            size: estimatedSize,
            dataUrl,
          });
        };

        image.src = originalDataUrl;
      };

      reader.readAsDataURL(file);
    });
  }

  async function addLogbookAttachments(files: FileList | null, type: "Bild" | "Dokument") {
    if (!files) return;

    try {
      const nextAttachments = await Promise.all(
        Array.from(files).map((file) => readLogbookAttachment(file, type))
      );
      const validationMessage = getLogbookAttachmentsValidationMessage([
        ...logbookAttachments,
        ...nextAttachments,
      ]);

      if (validationMessage) {
        setLogbookError(validationMessage);
        return;
      }

      setLogbookAttachments((currentAttachments) => [...currentAttachments, ...nextAttachments]);
      setLogbookError("");
    } catch (error) {
      setLogbookError(error instanceof Error ? error.message : "Anhang konnte nicht gelesen werden.");
    }
  }

  function getProjectLogbookAuthorUser(entry: ProjectLogbookEntry) {
    if (entry.authorUserId) {
      const userById = users.find((user) => user.id === entry.authorUserId);
      if (userById) return userById;
    }

    const authorName = entry.author.trim().toLowerCase();
    return authorName ? users.find((user) => user.name.trim().toLowerCase() === authorName) : undefined;
  }

  function isSystemLogbookAuthor(entry: ProjectLogbookEntry) {
    const author = entry.author.trim();
    return !author || /^system$/i.test(author);
  }

  function renderSystemLogbookAvatar() {
    return (
      <svg viewBox="0 0 24 24" aria-hidden="true" focusable="false">
        <path d="M12 3.5v2" />
        <rect x="5" y="7" width="14" height="11" rx="4" />
        <path d="M8 11.5h.01M16 11.5h.01" />
        <path d="M9.5 16h5" />
      </svg>
    );
  }

  function getProjectLogbookFallbackAuthorUser(actor: string) {
    const normalizedActor = actor.trim().toLowerCase();
    if (!normalizedActor || /^system$/i.test(normalizedActor)) return undefined;

    return users.find((user) => {
      const normalizedName = user.name.trim().toLowerCase();
      const normalizedInitials = getInitials(user.name).toLowerCase();
      return normalizedName === normalizedActor || normalizedInitials === normalizedActor;
    });
  }

  function renderProjectLogbookAvatar(entry: ProjectLogbookEntry) {
    const authorUser = getProjectLogbookAuthorUser(entry);
    if (authorUser?.profileImageDataUrl) {
      return <img src={authorUser.profileImageDataUrl} alt="" />;
    }

    if (isSystemLogbookAuthor(entry)) {
      return renderSystemLogbookAvatar();
    }

    return getInitials(authorUser?.name || entry.author || activeUser?.name || "MA");
  }

  function renderProjectLogbookFallbackAvatar(actor: string) {
    const fallbackUser = getProjectLogbookFallbackAuthorUser(actor);
    if (fallbackUser?.profileImageDataUrl) {
      return <img src={fallbackUser.profileImageDataUrl} alt="" />;
    }

    const normalizedActor = actor.trim();
    if (!normalizedActor || /^system$/i.test(normalizedActor)) {
      return renderSystemLogbookAvatar();
    }

    return getInitials(fallbackUser?.name || normalizedActor || activeUser?.name || "MA");
  }

  async function saveLogbookEntry() {
    if (!logbookMessage.trim()) return;

    const now = new Date();
    const date = new Intl.DateTimeFormat(APP_LOCALE, {
      day: "2-digit",
      month: "2-digit",
      year: "numeric",
      hour: "2-digit",
      minute: "2-digit",
      timeZone: APP_TIME_ZONE,
    }).format(now);
    const taskTitle = logbookCreateTask
      ? logbookTaskTitle.trim() || logbookMessage.trim().slice(0, 80)
      : "";
    const validationMessage = getLogbookAttachmentsValidationMessage(logbookAttachments);
    if (validationMessage) {
      setLogbookError(validationMessage);
      return;
    }

    if (logbookTarget === "project") {
      if (!selectedProjectFile) return;
      if (!activeUserId) {
        setLogbookError("Aktiver Benutzer konnte nicht eindeutig bestimmt werden.");
        return;
      }

      const res = await fetch("/api/project-logbook-entries", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          actorId: activeUserId,
          projectId: selectedProjectFile.id,
          title: "Eintrag",
          text: logbookMessage.trim(),
          author: activeUser?.name || "Christian Eid",
          authorUserId: activeUserId,
          colleague: logbookColleague.trim(),
          visibleFor: logbookVisibleFor,
          attachments: logbookAttachments,
        }),
      });

      if (!res.ok) {
        const data = await res.json().catch(() => null);
        setLogbookError(data?.error ?? "Logbucheintrag konnte nicht gespeichert werden.");
        return;
      }

      const savedEntry = (await res.json()) as ProjectLogbookEntry;
      setProjectLogbookEntries((currentEntries) => [savedEntry, ...currentEntries]);
      setIsLogbookModalOpen(false);
      resetLogbookDraft();
      return;
    }

    if (!selectedCustomerFile) return;

    setCustomerLogbookEntries((currentEntries) => [
      {
        id: `${selectedCustomerFile.id}-${now.getTime()}`,
        customerId: selectedCustomerFile.id,
        date,
        text: logbookMessage.trim(),
        colleague: logbookColleague.trim(),
        visibleFor: logbookVisibleFor,
        attachments: logbookAttachments,
        taskTitle,
      },
      ...currentEntries,
    ]);
    setIsLogbookModalOpen(false);

    if (logbookCreateTask) {
      resetForm();
      setTitel(taskTitle);
      setKunde(
        selectedCustomerFile.companyName ||
          [selectedCustomerFile.firstName, selectedCustomerFile.lastName].filter(Boolean).join(" ")
      );
      setBeschreibung(logbookMessage.trim());
      setIsModalOpen(true);
    }

    resetLogbookDraft();
  }

  async function uploadProjectImageCategory(category: string, files: FileList | null) {
    if (!selectedProjectFile || !files || files.length === 0) return;
    if (!activeUserId) {
      setLogbookError("Aktiver Benutzer konnte nicht eindeutig bestimmt werden.");
      return;
    }

    try {
      setLogbookError("");
      const isRecurringProject = getProjectKind(selectedProjectFile).startsWith("Dauer");
      const projectMonth = isRecurringProject
        ? projectComparisonMonth || formatDateKey(new Date()).slice(0, 7)
        : "";
      const imageNamePrefix =
        category === "Vorherbilder"
          ? "Vorherbild"
          : category === "Nachherbilder"
            ? "Nachherbild"
            : "Objektbild";
      const existingImageCount = projectLogbookEntries
        .filter((entry) => String(entry.projectId) === String(selectedProjectFile.id))
        .filter((entry) => entry.title === `Bilder: ${category}`)
        .filter((entry) => !projectMonth || entry.projectMonth === projectMonth)
        .reduce(
          (sum: number, entry: ProjectLogbookEntry) =>
            sum + entry.attachments.filter((attachment: LogbookAttachment) => attachment.type === "Bild").length,
          0
        );
      const uploadDate = formatDateForFileName(new Date());
      const attachments = await Promise.all(
        Array.from(files).map((file, fileIndex) =>
          readProjectImageAttachment(file, `${imageNamePrefix}_${existingImageCount + fileIndex + 1}_${uploadDate}`)
        )
      );
      const validationMessage = getLogbookAttachmentsValidationMessage(attachments);
      if (validationMessage) {
        setLogbookError(validationMessage);
        return;
      }

      const res = await fetch("/api/project-logbook-entries", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          actorId: activeUserId,
          projectId: selectedProjectFile.id,
          title: `Bilder: ${category}`,
          text: `${category} hochgeladen`,
          author: activeUser?.name || "Christian Eid",
          authorUserId: activeUserId,
          colleague: "",
          visibleFor: [
            "Geschaeftsfuehrer",
            "Vertriebler",
            "Niederlassungsleiter",
            "Monteur",
            "Buchhaltung",
          ],
          attachments,
          projectMonth,
        }),
      });

      if (!res.ok) {
        const data = await res.json().catch(() => null);
        setLogbookError(data?.error ?? `Bilder konnten nicht gespeichert werden. Status ${res.status}.`);
        return;
      }

      const savedEntry = (await res.json()) as ProjectLogbookEntry;
      setProjectLogbookEntries((currentEntries) => [savedEntry, ...currentEntries]);
      setLogbookError("");
      if (category === "Vorherbilder" || category === "Nachherbilder") {
        await confirmImplementationStatus(
          selectedProjectFile,
          `Ausfuehrungsnachweis hochgeladen: ${category}`
        );
        await notifyProjectBillingReady(selectedProjectFile, projectMonth || getCurrentMonthKey());
      }
    } catch (error) {
      setLogbookError(error instanceof Error ? error.message : "Bilder konnten nicht hochgeladen werden.");
    }
  }

  function applyProjectLogbookAttachmentPatch(data: ProjectLogbookAttachmentPatchResponse) {
    setProjectLogbookEntries((currentEntries) => {
      const upsertEntry = (entries: ProjectLogbookEntry[], nextEntry?: ProjectLogbookEntry) => {
        if (!nextEntry) return entries;
        const exists = entries.some((entry) => entry.id === nextEntry.id);
        return exists
          ? entries.map((entry) => (entry.id === nextEntry.id ? nextEntry : entry))
          : [nextEntry, ...entries];
      };

      let nextEntries = upsertEntry(currentEntries, data.entry);
      nextEntries = upsertEntry(nextEntries, data.targetEntry);
      nextEntries = upsertEntry(nextEntries, data.history);
      return nextEntries;
    });
  }

  async function updateProjectImageAttachment(
    entryId: string,
    attachmentIndex: number,
    attachmentName: string,
    action: "delete" | "move",
    targetCategory?: string
  ) {
    if (!selectedProjectFile) return;
    if (!activeUserId) {
      setLogbookError("Aktiver Benutzer konnte nicht eindeutig bestimmt werden.");
      return;
    }
    if (action === "delete" && !window.confirm(`Bild "${attachmentName}" wirklich löschen?`)) return;

    try {
      setLogbookError("");
      const res = await fetch("/api/project-logbook-entries", {
        method: "PATCH",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          actorId: activeUserId,
          entryId,
          attachmentIndex,
          attachmentName,
          action,
          targetTitle: targetCategory ? `Bilder: ${targetCategory}` : "",
          actorUserId: activeUserId,
          actorName: activeUser?.name || "Christian Eid",
        }),
      });

      if (!res.ok) {
        const data = await res.json().catch(() => null);
        setLogbookError(data?.error ?? "Bild konnte nicht aktualisiert werden.");
        return;
      }

      const data = (await res.json()) as ProjectLogbookAttachmentPatchResponse;
      applyProjectLogbookAttachmentPatch(data);
    } catch (error) {
      setLogbookError(error instanceof Error ? error.message : "Bild konnte nicht aktualisiert werden.");
    }
  }

