  async function startStampSession(mode: StampMode, projectId: string, comment: string, unproductiveLabel = "") {
    const normalizedUnproductiveLabel = unproductiveLabel.trim();
    const projectLabel =
      mode === "project" ? getStampProjectLabel(projectId) : normalizedUnproductiveLabel || "Unproduktiv";
    const res = await fetch("/api/stamp-session", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        action: "start",
        userId: activeUser?.id || activeUserId,
        employee: activeUser?.name || "Aktueller Mitarbeiter",
        mode,
        projectId: mode === "project" ? projectId : "__unproductive__",
        projectLabel,
        comment,
      }),
    });

    if (!res.ok) {
      const data = await res.json().catch(() => null);
      setStampError(data?.error ?? "Stempelung konnte nicht gestartet werden.");
      throw new Error(data?.error ?? "Stempelung konnte nicht gestartet werden.");
    }

    const data = (await res.json()) as ActiveStampSessionResponse;
    setStampSession(mapActiveStampSession(data));
    setTimerNow(Date.now());
  }

  async function saveStampTimeEntry(entry: StampTimeEntry) {
    const projectId =
      entry.mode === "project"
        ? String(entry.projectId ?? "").trim()
        : "__unproductive__";

    const res = await fetch("/api/project-time-entries", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        ...entry,
        projectId,
        actorUserId: activeUserId,
        actorName: activeUser?.name ?? "",
      }),
    });

    if (!res.ok) {
      const data = await res.json().catch(() => null);
      setStampError(data?.error ?? "Projektzeit konnte nicht gespeichert werden.");
      throw new Error(data?.error ?? "Projektzeit konnte nicht gespeichert werden.");
    }

    const savedEntry = (await res.json()) as StampTimeEntry;
    const normalizedSavedEntry = { ...savedEntry, date: normalizeDateKeyValue(savedEntry.date) };
    setStampEntries((currentEntries) => [
      normalizedSavedEntry,
      ...currentEntries.filter((currentEntry) => currentEntry.id !== normalizedSavedEntry.id),
    ]);
  }

  async function approveOvertimeForDay(userId: string, dateKey: string) {
    if (!canManageAbsences(activeUser?.role)) return;

    const entriesToApprove = stampEntries.filter((entry) => !entry.deletedAt && entry.userId === userId && entry.date === dateKey);
    if (entriesToApprove.length === 0) return;

    try {
      await Promise.all(
        entriesToApprove.map((entry) =>
          saveStampTimeEntry({
            ...entry,
            overtimeApprovalStatus: "approved",
            overtimeApprovedByUserId: activeUserId,
            overtimeApprovedByName: activeUser?.name ?? "",
            overtimeApprovedAt: new Date().toISOString(),
          })
        )
      );
      await loadProjectTimeEntries();
    } catch {
      setErrorMessage("Überstunden konnten nicht freigegeben werden.");
    }
  }

  function parseStampTimeToMinutes(value: string) {
    const [hours, minutes] = value.split(":").map((part) => Number(part));
    if (!Number.isInteger(hours) || !Number.isInteger(minutes)) return null;
    if (hours < 0 || hours > 23 || minutes < 0 || minutes > 59) return null;
    return hours * 60 + minutes;
  }

  function parseStampPauseToMilliseconds(value: string) {
    const trimmedValue = value.trim();
    if (!trimmedValue) return 0;
    const parts = trimmedValue.split(":").map((part) => Number(part));
    if (parts.some((part) => !Number.isFinite(part) || part < 0)) return null;

    if (parts.length === 2) {
      const [hours, minutes] = parts;
      if (!Number.isInteger(hours) || !Number.isInteger(minutes) || minutes > 59) return null;
      return (hours * 60 + minutes) * 60_000;
    }

    if (parts.length === 3) {
      const [hours, minutes, seconds] = parts;
      if (
        !Number.isInteger(hours) ||
        !Number.isInteger(minutes) ||
        !Number.isInteger(seconds) ||
        minutes > 59 ||
        seconds > 59
      ) {
        return null;
      }
      return ((hours * 60 + minutes) * 60 + seconds) * 1000;
    }

    return null;
  }

