  function getSafeWeeklyCapacity(value?: Partial<WeeklyCapacity>) {
    return Object.fromEntries(
      weeklyCapacityDayLabels.map(({ key }) => {
        const hours = Number(value?.[key] ?? defaultWeeklyCapacity[key]);
        return [key, Number.isFinite(hours) && hours >= 0 ? hours : defaultWeeklyCapacity[key]];
      })
    ) as WeeklyCapacity;
  }

  function getPlanningGroupsForBoard(board: string) {
    return planningBoardGroupsByCompany[board as PlanningBoardCompany] ?? planningBoardGroupsByCompany["OK solutions"];
  }

  function getPlanningResponsibilityKey(board: PlanningBoardCompany, group: string) {
    return `${board}:${group}`;
  }

  function getTeamIdsForPlanningBoard(board: PlanningBoardCompany) {
    const boardNeedle = board.toLowerCase();
    const matchingTeams = teams.filter((team) => team.name.toLowerCase().includes(boardNeedle));
    return matchingTeams.length > 0 ? matchingTeams.map((team) => team.id) : [];
  }

  function getTeamIdsForBranchAllocations(allocations: BranchAllocations) {
    return Array.from(
      new Set([
        ...(allocations.okSolutions > 0 ? getTeamIdsForPlanningBoard("OK solutions") : []),
        ...(allocations.okImmocare > 0 ? getTeamIdsForPlanningBoard("OK immocare") : []),
      ])
    );
  }

  function updateEmployeeBranch(board: PlanningBoardCompany) {
    const nextAllocations = getDefaultBranchAllocations(board);
    const nextGroups = getPlanningGroupsForBoard(board);
    setEmployeePlanningBoard(board);
    setEmployeePlanningGroup(nextGroups[0]);
    setEmployeeBranchAllocations(nextAllocations);
    setUserTeamIds(getTeamIdsForBranchAllocations(nextAllocations));
    setUserAllTeams(false);
  }

  function updateEmployeeBranchAllocations(patch: Partial<BranchAllocations>) {
    const merged = {
      ...employeeBranchAllocations,
      ...patch,
    };
    const nextAllocations = normalizeBranchAllocations({
      ...merged,
      okImmocare: Number(merged.okImmocareVzk ?? 0) + Number(merged.okImmocareTzk ?? 0),
    });
    const nextBoard = getPrimaryBranchFromAllocations(nextAllocations);
    const nextGroups = getPlanningGroupsForBoard(nextBoard);
    setEmployeeBranchAllocations(nextAllocations);
    setEmployeePlanningBoard(nextBoard);
    setEmployeePlanningGroup((current) => (nextGroups.includes(current) ? current : nextGroups[0]));
    setUserTeamIds(getTeamIdsForBranchAllocations(nextAllocations));
    setUserAllTeams(false);
  }

  function setEmployeeBranchAllocationValue(
    key: "okSolutions" | "okImmocareVzk" | "okImmocareTzk",
    rawValue: number
  ) {
    const nextAllocations = createBoundedBranchAllocations(employeeBranchAllocations, key, rawValue);
    updateEmployeeBranchAllocations(nextAllocations);
  }

  function togglePlanningResponsibility(key: string, enabled: boolean) {
    setEmployeePlanningResponsibleFor((current) => {
      if (enabled) return current.includes(key) ? current : [...current, key];
      return current.filter((entry) => entry !== key);
    });
  }

  function setEmployeeWeeklyCapacityDay(day: WeeklyDayKey, value: string) {
    const hours = Number(value);
    setEmployeeWeeklyCapacity((current) => ({
      ...current,
      [day]: Number.isFinite(hours) && hours >= 0 ? hours : 0,
    }));
  }

  function getSafePlanningTime(value: string | undefined, fallback: string) {
    return value !== undefined && (value === "" || /^\d{2}:\d{2}$/.test(value)) ? value : fallback;
  }

  function getSafePlanningTimeWindows(
    value?: Partial<Record<WeeklyDayKey, Partial<PlanningTimeWindow>>>,
    fallbackStart = "08:00",
    fallbackEnd = "17:00"
  ) {
    return Object.fromEntries(
      weeklyCapacityDayLabels.map(({ key }) => {
        const entry = value?.[key];
        return [
          key,
          {
            start: getSafePlanningTime(entry?.start, fallbackStart),
            end: getSafePlanningTime(entry?.end, fallbackEnd),
          },
        ];
      })
    ) as WeeklyPlanningWindows;
  }

  function setEmployeePlanningWindowDay(
    day: WeeklyDayKey,
    field: keyof PlanningTimeWindow,
    value: string
  ) {
    setEmployeePlanningTimeWindows((current) => ({
      ...current,
      [day]: {
        ...current[day],
        [field]: getSafePlanningTime(value, field === "start" ? "08:00" : "17:00"),
      },
    }));
  }

  function setEmployeePlanningBreakDay(
    day: WeeklyDayKey,
    field: keyof PlanningTimeWindow,
    value: string
  ) {
    setEmployeePlanningBreakWindows((current) => ({
      ...current,
      [day]: {
        ...current[day],
        [field]: getSafePlanningTime(value, ""),
      },
    }));
  }

  function editUser(user: UserOption) {
    setEditingUserId(user.id);
    setUserName(user.name);
    setUserEmail(user.email);
    setUserRole(user.role);
    setUserDailyWorkHours(user.dailyWorkHours.toString());
    setUserPassword("");
    setUserProfileImageDataUrl(user.profileImageDataUrl ?? "");
    setEmployeePersonalNumber(user.personalNumber ?? "");
    setEmployeeSalutation(user.salutation || "Herr");
    setEmployeeBirthDate(user.birthDate || "");
    setEmployeeLanguage(user.language || "Deutsch (Deutschland)");
    setEmployeePhone(user.phone || "");
    setEmployeeMobile(user.mobile || "");
    setEmployeeStreet(user.street || "");
    setEmployeePostalCode(user.postalCode || "");
    setEmployeeCity(user.city || "");
    setEmployeeSignatureHidden(Boolean(user.signatureHidden));
    setEmployeeSignature(user.signature || getDefaultSignatureSource(user));
    const planningBoard = (user.planningBoard === "OK immocare" ? "OK immocare" : "OK solutions") as PlanningBoardCompany;
    const branchAllocations = normalizeBranchAllocations(user.branchAllocations, planningBoard);
    const planningGroups = getPlanningGroupsForBoard(planningBoard);
    setEmployeePlanningBoard(planningBoard);
    setEmployeeBranchAllocations(branchAllocations);
    setEmployeePlanningGroup(
      user.planningGroup && planningGroups.includes(user.planningGroup)
        ? user.planningGroup
        : planningGroups[0]
    );
    setEmployeeWeeklyCapacity(getSafeWeeklyCapacity(user.weeklyCapacity));
    setEmployeePlanningStartTime(getSafePlanningTime(user.planningStartTime, "08:00"));
    setEmployeePlanningEndTime(getSafePlanningTime(user.planningEndTime, "17:00"));
    setEmployeePlanningTimeWindows(
      getSafePlanningTimeWindows(
        user.planningTimeWindows,
        getSafePlanningTime(user.planningStartTime, "08:00"),
        getSafePlanningTime(user.planningEndTime, "17:00")
      )
    );
    setEmployeePlanningBreakWindows(
      getSafePlanningTimeWindows(user.planningBreakWindows, "12:00", "12:30")
    );
    setEmployeePlanningResponsibleFor(user.planningResponsibleFor ?? []);
    setEmployeeIncludeInLaborCostRate(user.includeInLaborCostRate !== false);
    setEmployeeNotifyIdeaStore(user.notifyIdeaStore ?? true);
    setEmployeeNotifyUpsell(user.notifyUpsell ?? false);
    setEmployeeMailAccount(getSafeEmployeeMailAccount(user.mailAccount, user.email));
    setEmployeeMailMessage("");
    setEmployeePasswordMessage("");
    setUserTeamIds(getTeamIdsForBranchAllocations(branchAllocations));
    setUserAllTeams(false);
    setErrorMessage("");
  }

  function generateUserPassword() {
    const alphabet = "ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789";
    const generatedPassword = Array.from({ length: 10 }, () =>
      alphabet[Math.floor(Math.random() * alphabet.length)]
    ).join("");

    setUserPassword(generatedPassword);
    setEmployeePasswordMessage("");
  }

  async function handleEmployeeProfileImageUpload(file: File | null) {
    if (!file) return;

    if (!file.type.startsWith("image/")) {
      setErrorMessage("Bitte eine Bilddatei als Profilbild auswählen.");
      return;
    }

    try {
      setUserProfileImageDataUrl(await resizeProfileImage(file));
      setErrorMessage("");
    } catch (error) {
      setErrorMessage(
        error instanceof Error ? error.message : "Profilbild konnte nicht verarbeitet werden."
      );
    }
  }

  function getLoginCredentialsMessage(credentials: LoginCredentialsDraft) {
    const loginUrl = typeof window !== "undefined" ? `${window.location.origin}/dashboard` : "";

    return [
      `Hallo ${credentials.name},`,
      "",
      "dein WorkPilot-Zugang wurde eingerichtet.",
      "",
      `Login: ${loginUrl}`,
      `E-Mail: ${credentials.email}`,
      `Passwort: ${credentials.password}`,
      "",
      "Bitte melde dich mit diesen Zugangsdaten an.",
    ].join("\n");
  }

  async function copyLoginCredentials() {
    if (!loginCredentialsDraft || typeof navigator === "undefined") return;
    await navigator.clipboard?.writeText(getLoginCredentialsMessage(loginCredentialsDraft));
  }

  function connectEmployeeMicrosoftMail() {
    const targetUserId = editingUserId || selectedEmployeeId;
    if (!targetUserId || targetUserId === "__new__" || !activeUserId) {
      setEmployeeMailMessage("Bitte den Mitarbeiter zuerst speichern, danach kann Microsoft 365 verbunden werden.");
      return;
    }

    const returnTo =
      typeof window !== "undefined"
        ? `${window.location.pathname}${window.location.search}`
        : "/dashboard";
    window.location.href = `/api/mail/oauth/start?userId=${encodeURIComponent(targetUserId)}&actorId=${encodeURIComponent(activeUserId)}&returnTo=${encodeURIComponent(returnTo)}`;
  }

  function disconnectEmployeeMicrosoftMail() {
    setEmployeeMailAccount({
      ...emptyEmployeeMailAccount,
      email: userEmail,
    });
    setEmployeeMailMessage("E-Mail-Konto wurde getrennt.");
  }

  function markEmployeeMailTest() {
    setEmployeeMailAccount((current) => ({
      ...getSafeEmployeeMailAccount(current, userEmail),
      lastTestAt: new Date().toISOString(),
    }));
    setEmployeeMailMessage("Test-E-Mail wurde vorgemerkt. Nach OAuth-Aktivierung wird sie direkt über Microsoft 365 gesendet.");
  }

  function toggleUserTeam(teamId: string, checked: boolean) {
    setUserTeamIds((current) =>
      {
        const next = checked
          ? Array.from(new Set([...current, teamId]))
          : current.filter((id) => id !== teamId);

        setUserAllTeams(teams.length > 0 && next.length === teams.length);
        return next;
      }
    );
  }

