  async function deleteUser(userId: string) {
    const confirmed = window.confirm("Mitarbeiter wirklich auf inaktiv setzen?");
    if (!confirmed) return;

    const res = await fetch("/api/users", {
      method: "DELETE",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify({ userId, actorId: activeUserId }),
    });

    if (!res.ok) {
      const data = await res.json().catch(() => null);
      setErrorMessage(data?.error ?? "Benutzer konnte nicht entfernt werden.");
      return;
    }

    if (editingUserId === userId) resetUserForm();
    if (selectedEmployeeId === userId) setSelectedEmployeeId("");
    setEmployeeStatusView("inactive");
    await loadUsers();
    await loadTasks();
  }

  async function restoreUser(userId: string) {
    const res = await fetch("/api/users", {
      method: "PATCH",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        action: "set-active",
        userId,
        isActive: true,
        actorId: activeUserId,
      }),
    });

    if (!res.ok) {
      const data = await res.json().catch(() => null);
      setErrorMessage(data?.error ?? "Mitarbeiter konnte nicht reaktiviert werden.");
      return;
    }

    setEmployeeStatusView("active");
    await loadUsers();
  }

  const holidayDateKeys = new Set(holidays.map((holiday) => holiday.date));
  const activeTasks = tasks.filter((task) => task.status !== "archiviert");
  const archivedTasks = tasks.filter((task) => task.status === "archiviert");
  const isManagingDirector = activeUser?.role === "GESCHAEFTSFUEHRER";
  const isActiveUserProjectParticipant = (task: TaskItem) => {
    if (!activeUser || !task.projectId) return false;

    const project = heroProjects.find((item) => item.id === task.projectId);
    if (!project) return false;

    const activeUserName = activeUser.name.trim().toLowerCase();
    const activeUserEmail = activeUser.email.trim().toLowerCase();
    const participantText = [project.responsibleName, project.participants]
      .filter(Boolean)
      .join(" ")
      .toLowerCase();

    return (
      Boolean(activeUserName && participantText.includes(activeUserName)) ||
      Boolean(activeUserEmail && participantText.includes(activeUserEmail))
    );
  };
  const isTaskEscalatedToActiveUser = (task: TaskItem) => {
    if (!activeUser?.role || task.status === "erledigt" || task.status === "abgelehnt") return false;

    const deadline = parseAppDateTime(task.faelligkeit);
    if (!Number.isFinite(deadline.getTime())) return false;

    const hoursAfterDue = (deadlineProgressTime - deadline.getTime()) / 3_600_000;
    if (hoursAfterDue < 0) return false;

    return isManagingDirector || isActiveUserProjectParticipant(task);
  };
  const myRelevantTasks = activeTasks.filter(
    (task) =>
      task.createdById === activeUserId ||
      task.zustaendigId === activeUserId ||
      task.participants.some((participant) => participant.userId === activeUserId) ||
      isTaskEscalatedToActiveUser(task)
  );
  const taskOverviewTasks = canManageUsers(activeUser?.role) ? activeTasks : myRelevantTasks;
  const offene = taskOverviewTasks.filter((task) => task.status === "offen").length;
  const bearbeitung = taskOverviewTasks.filter((task) => task.status === "in Bearbeitung").length;
  const erledigt = taskOverviewTasks.filter((task) => task.status === "erledigt").length;
  const ueberfaellig = taskOverviewTasks.filter(
    (task) => isTaskOverdueByWorkingTime(task, deadlineProgressTime, holidayDateKeys)
  ).length;
  const mayManageUsers = canManageUsers(activeUser?.role);
  const mayApproveContent =
    mayManageUsers ||
    activeUser?.role === "FUEHRUNGSKRAFT" ||
    /pauline/i.test(activeUser?.name ?? "");
  const mayFilterPlanningUsers = canAssignOther(activeUser?.role);
  const effectivePlanningOwnerFilter = mayFilterPlanningUsers
    ? planningOwnerFilter || ""
    : activeUserId;
  const customerOptions = Array.from(
    new Set([
      ...heroProjects.map((project) => project.customer).filter(Boolean),
      ...activeTasks.map((task) => task.kunde).filter(Boolean),
    ])
  ).sort((first, second) => first.localeCompare(second, "de"));
  const filteredHeroProjects = kunde
    ? heroProjects.filter((project) => project.customer === kunde)
    : [];
  const selectedHeroDetail = heroProjects.find((project) => project.id === selectedHeroDetailId);
  const selectedProjectFile =
    heroProjects.find((project) => project.id === selectedProjectFileId) ?? null;
  function openProjectFile(
    project: HeroProjectPreview,
    options: {
      tab?: ProjectFileTab;
      activeTab?: AppTab;
      documentType?: CustomerDocumentType;
      month?: string;
      keepMonth?: boolean;
    } = {}
  ) {
    if (isAccountingRole(activeUser?.role)) {
      return;
    }

    if (options.activeTab) {
      setActiveTab(options.activeTab);
    } else {
      const projectType = (project.projectType ?? "").toLowerCase();
      const projectNumber = (project.projectNumber ?? "").toLowerCase();
      setActiveTab(
        projectType.includes("immocare") || projectNumber.startsWith("oki")
          ? "projectsImmocare"
          : "projectsSolutions"
      );
    }

    setSelectedProjectFileId(project.id);
    setProjectFileTab(options.tab ?? "logbook");

    if (options.documentType) {
      setSelectedProjectDocumentType(options.documentType);
    }

    if (/^\d{4}-\d{2}$/.test(options.month ?? "")) {
      setProjectComparisonMonth(options.month ?? "");
      return;
    }

    if (!options.keepMonth && getProjectKind(project).startsWith("Dauer")) {
      setProjectComparisonMonth(getCurrentMonthKey());
    }
  }
  const isRestoringProjectFile =
    Boolean(selectedProjectFileId) &&
    (activeTab === "hero" || activeTab === "projectsSolutions" || activeTab === "projectsImmocare") &&
    !selectedProjectFile &&
    (!hasLoadedHeroProjects || isHeroProjectsLoading);
  const activeProjectPipeline =
    projectPipelines.find((pipeline) => pipeline.tab === activeTab) ?? projectPipelines[0];
  const getProjectPotentialEntries = (projectId: string) =>
    projectPotentials.filter(
      (potential) =>
        String(potential.projectId) === String(projectId) &&
        ["open", "follow_up"].includes(potential.status)
    );
  const hasProjectPotential = (project: HeroProjectPreview) =>
    getProjectPotentialEntries(project.id).length > 0;
  const buildAccountingDocumentSearchText = (parts: Array<string | number | undefined>) =>
    parts
      .filter((part) => part !== undefined && part !== null && String(part).trim().length > 0)
      .join(" ")
      .toLocaleLowerCase(APP_LOCALE);
  const accountingDocumentRows: AccountingDocumentRow[] = [
    ...offers.map((offer) => {
      const project = heroProjects.find((item) => item.id === offer.projectId);
      const type: AccountingDocumentRow["type"] = offer.offerType === "addendum" ? "Angebot" : "Angebot";
      const projectLabel = [offer.projectNumber, offer.projectTitle].filter(Boolean).join(" | ");

      return {
        id: `offer-${offer.id}`,
        type,
        number: offer.offerNumber,
        customerName: offer.customerName,
        projectLabel,
        date: offer.createdAt,
        amount: Number(offer.netTotal) || 0,
        status: offer.status,
        source: "WorkPilot",
        project,
        projectDocumentType: "Angebote" as CustomerDocumentType,
        searchText: buildAccountingDocumentSearchText([
          type,
          offer.offerNumber,
          offer.customerName,
          projectLabel,
          offer.status,
          offer.company,
          Number(offer.netTotal) || 0,
        ]),
      };
    }),
    ...invoices.map((invoice) => {
      const project = heroProjects.find((item) => item.id === invoice.projectId);
      const lowerStatus = invoice.status.toLocaleLowerCase(APP_LOCALE);
      const lowerNumber = invoice.invoiceNumber.toLocaleLowerCase(APP_LOCALE);
      const type: AccountingDocumentRow["type"] =
        lowerStatus.includes("storno") || lowerNumber.includes("storno") ? "Storno" : "Rechnung";
      const projectLabel = [invoice.projectNumber, invoice.projectTitle].filter(Boolean).join(" | ");

      return {
        id: `invoice-${invoice.id}`,
        type,
        number: invoice.invoiceNumber,
        customerName: invoice.customerName,
        projectLabel,
        date: invoice.serviceDate || invoice.createdAt,
        amount: Number(invoice.netTotal) || 0,
        status: invoice.status,
        source: invoice.billingSource === "batch" ? "WorkPilot Stapel" : "WorkPilot",
        project,
        projectDocumentType: "Rechnungen" as CustomerDocumentType,
        searchText: buildAccountingDocumentSearchText([
          type,
          invoice.invoiceNumber,
          invoice.customerName,
          projectLabel,
          invoice.status,
          invoice.company,
          Number(invoice.netTotal) || 0,
        ]),
      };
    }),
    ...legacyInvoices.map((invoice) => {
      const type: AccountingDocumentRow["type"] = "Rechnung ALT";

      return {
        id: `legacy-${invoice.id}`,
        type,
        number: invoice.invoiceNumber,
        customerName: invoice.customerName,
        projectLabel: invoice.projectAddress,
        date: invoice.invoiceDate,
        amount: Number(invoice.netTotal) || 0,
        status: invoice.status,
        source: invoice.source || "HERO",
        searchText: buildAccountingDocumentSearchText([
          type,
          invoice.invoiceNumber,
          invoice.fileName,
          invoice.customerName,
          invoice.projectAddress,
          invoice.status,
          invoice.company,
          Number(invoice.netTotal) || 0,
        ]),
      };
    }),
  ].sort((first, second) => {
    const firstDate = parseProjectDate(first.date)?.getTime() ?? 0;
    const secondDate = parseProjectDate(second.date)?.getTime() ?? 0;
    return secondDate - firstDate;
  });
  const filteredAccountingDocumentRows = accountingDocumentRows.filter((row) => {
    if (accountingDocumentTypeFilter === "offers" && row.type !== "Angebot") return false;
    if (accountingDocumentTypeFilter === "invoices" && row.type !== "Rechnung") return false;
    if (accountingDocumentTypeFilter === "cancellations" && row.type !== "Storno") return false;
    if (accountingDocumentTypeFilter === "legacy" && row.type !== "Rechnung ALT") return false;

    const customerProjectQuery = accountingDocumentCustomerProjectFilter.trim().toLocaleLowerCase(APP_LOCALE);
    if (
      customerProjectQuery &&
      !buildAccountingDocumentSearchText([row.customerName, row.projectLabel]).includes(customerProjectQuery)
    ) {
      return false;
    }

    const fullTextQuery = accountingDocumentSearch.trim().toLocaleLowerCase(APP_LOCALE);
    return !fullTextQuery || row.searchText.includes(fullTextQuery);
  });
  const accountingDocumentSummary = {
    total: accountingDocumentRows.length,
    offers: accountingDocumentRows.filter((row) => row.type === "Angebot").length,
    invoices: accountingDocumentRows.filter((row) => row.type === "Rechnung").length,
    cancellations: accountingDocumentRows.filter((row) => row.type === "Storno").length,
    legacy: accountingDocumentRows.filter((row) => row.type === "Rechnung ALT").length,
  };
  const resetAccountingDocumentFilters = () => {
    setAccountingDocumentSearch("");
    setAccountingDocumentCustomerProjectFilter("");
    setAccountingDocumentTypeFilter("all");
  };
  function renderAccountingDocuments() {
    return (
      <section className={styles.settingsPanel}>
        <div className={styles.topline}>
          <div>
            <p className={styles.eyebrow}>Buchhaltung</p>
            <h1>Dokumente</h1>
            <p className={styles.subline}>
              Zentrale Ablage für erzeugte kaufmännische Dokumente inklusive HERO-Altrechnungen.
            </p>
          </div>
        </div>

        <section className={styles.accountingDocumentSummaryGrid}>
          <article>
            <span>Gesamt</span>
            <strong>{accountingDocumentSummary.total}</strong>
            <small>Dokumente</small>
          </article>
          <article>
            <span>Angebote</span>
            <strong>{accountingDocumentSummary.offers}</strong>
            <small>inkl. Nachträge</small>
          </article>
          <article>
            <span>Rechnungen</span>
            <strong>{accountingDocumentSummary.invoices}</strong>
            <small>WorkPilot</small>
          </article>
          <article>
            <span>Stornos</span>
            <strong>{accountingDocumentSummary.cancellations}</strong>
            <small>Gutschriften / Storno</small>
          </article>
          <article>
            <span>Rechnung ALT</span>
            <strong>{accountingDocumentSummary.legacy}</strong>
            <small>HERO-Import</small>
          </article>
        </section>

        <section className={`${styles.stampSearchBar} ${styles.accountingDocumentFilters}`}>
          <label>
            Kunde / Projekt
            <input
              type="search"
              value={accountingDocumentCustomerProjectFilter}
              onChange={(event) => setAccountingDocumentCustomerProjectFilter(event.target.value)}
              placeholder="Kunde, Projekt oder Adresse suchen..."
            />
          </label>
          <label>
            Volltextsuche
            <input
              type="search"
              value={accountingDocumentSearch}
              onChange={(event) => setAccountingDocumentSearch(event.target.value)}
              placeholder="Dokumentnummer, Status, Datei, Betrag..."
            />
          </label>
          <label>
            Dokumenttyp
            <select
              value={accountingDocumentTypeFilter}
              onChange={(event) => setAccountingDocumentTypeFilter(event.target.value as AccountingDocumentTypeFilter)}
            >
              <option value="all">Alle Dokumente</option>
              <option value="offers">Angebote</option>
              <option value="invoices">Rechnungen</option>
              <option value="cancellations">Stornos</option>
              <option value="legacy">Rechnung ALT</option>
            </select>
          </label>
          <button type="button" className={styles.secondaryButton} onClick={resetAccountingDocumentFilters}>
            Zurücksetzen
          </button>
          <span className={styles.stampSearchResult}>{filteredAccountingDocumentRows.length} Treffer</span>
        </section>

        <section className={styles.tableCard}>
          <table className={styles.table}>
            <thead>
              <tr>
                <th>Dokument</th>
                <th>Typ</th>
                <th>Kunde</th>
                <th>Projekt / Bezug</th>
                <th>Datum</th>
                <th>Betrag netto</th>
                <th>Status</th>
                <th>Quelle</th>
                <th>Aktion</th>
              </tr>
            </thead>
            <tbody>
              {filteredAccountingDocumentRows.length === 0 ? (
                <tr>
                  <td colSpan={9}>Keine Dokumente gefunden.</td>
                </tr>
              ) : (
                filteredAccountingDocumentRows.map((row) => (
                  <tr key={row.id}>
                    <td>
                      <strong>{row.number || "-"}</strong>
                    </td>
                    <td>{row.type}</td>
                    <td>{row.customerName || "-"}</td>
                    <td>{row.projectLabel || "-"}</td>
                    <td>{formatProjectDate(row.date)}</td>
                    <td>{formatMoney(row.amount)}</td>
                    <td>
                      <span className={styles.invoiceStatusChip} data-status={row.status}>
                        {row.status || "-"}
                      </span>
                    </td>
                    <td>{row.source}</td>
                    <td>
                      {row.project && row.projectDocumentType ? (
                        <button
                          type="button"
                          className={styles.secondaryButton}
                          onClick={() =>
                            openProjectFile(row.project as HeroProjectPreview, {
                              tab: "documents",
                              documentType: row.projectDocumentType,
                            })
                          }
                        >
                          Projekt öffnen
                        </button>
                      ) : (
                        <span className={styles.accountingDocumentMuted}>Kein Projekt verknüpft</span>
                      )}
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </section>
      </section>
    );
  }
  const activePipelineProjects = heroProjects.filter((project) => {
    const projectType = (project.projectType ?? "").toLowerCase();
    const projectNumber = (project.projectNumber ?? "").toLowerCase();

    if (activeProjectPipeline.id === "immocare") {
      return projectType.includes("immocare") || projectNumber.startsWith("oki");
    }

    return (
      projectType.includes("solutions") ||
      projectNumber.startsWith("oks") ||
      (!projectType.includes("immocare") && !projectNumber.startsWith("oki"))
    );
  });
  const activePipelineProjectIds = new Set(activePipelineProjects.map((project) => project.id));
  const activePipelinePotentials = projectPotentials.filter((potential) =>
    activePipelineProjectIds.has(potential.projectId)
  );
  const visiblePotentialRows = projectPotentials.filter((potential) => {
    if (potentialStatusFilter === "due") {
      const followUpTime = potential.followUpAt ? new Date(potential.followUpAt).getTime() : NaN;
      if (potential.status !== "follow_up" || !Number.isFinite(followUpTime) || followUpTime > Date.now()) {
        return false;
      }
    } else if (potentialStatusFilter !== "all" && potential.status !== potentialStatusFilter) {
      return false;
    }

    const project = getPotentialProject(potential);
    const search = heroSearchTerm.trim().toLowerCase();
    if (!search) return true;

    return [
      potential.description,
      potential.customerName,
      potential.projectLabel,
      getPotentialStatusLabel(potential),
      project?.projectNumber,
      project?.title,
      project?.customer,
    ]
      .filter(Boolean)
      .join(" ")
      .toLowerCase()
      .includes(search);
  });
  const filteredPipelinePotentials = activePipelinePotentials.filter((potential) =>
    visiblePotentialRows.some((visiblePotential) => visiblePotential.id === potential.id)
  );
  const getPotentialStatusCount = (filter: typeof potentialStatusFilter) => {
    const sourcePotentials = projectPotentials;

    if (filter === "all") {
      return sourcePotentials.length;
    }
    if (filter === "due") {
      return sourcePotentials.filter((potential) => {
        const followUpTime = potential.followUpAt ? new Date(potential.followUpAt).getTime() : NaN;
        return potential.status === "follow_up" && Number.isFinite(followUpTime) && followUpTime <= Date.now();
      }).length;
    }

    return sourcePotentials.filter((potential) => potential.status === filter).length;
  };
  const projectKindRows: Array<{
    key: ProjectKindFilter;
    label: string;
    count: number;
  }> = [
    {
      key: RECURRING_PROJECT_KIND,
      label: "Dauerläufer-Projekte",
      count: activePipelineProjects.filter(
        (project) => isRecurringProjectKindValue(getProjectKind(project))
      ).length,
    },
    {
      key: ONE_TIME_PROJECT_KIND,
      label: "Einmalige-Projekte",
      count: activePipelineProjects.filter(
        (project) => normalizeProjectKindValue(getProjectKind(project)) === ONE_TIME_PROJECT_KIND
      ).length,
    },
    {
      key: "potentials",
      label: "Zusatzverkäufe",
      count: getPotentialStatusCount("all"),
    },
  ];
  const visibleHeroProjects = activePipelineProjects.filter((project) => {
    if (selectedProjectKindFilter === "potentials") {
      if (!hasProjectPotential(project)) return false;
    } else if (
      selectedProjectKindFilter &&
      normalizeProjectKindValue(getProjectKind(project)) !== normalizeProjectKindValue(selectedProjectKindFilter)
    ) {
      return false;
    }

    if (
      selectedProjectPipelineStatus !== "Alle Offenen" &&
      normalizeProjectPipelineStatus(project.status) !== normalizeProjectPipelineStatus(selectedProjectPipelineStatus)
    ) {
      return false;
    }

    const search = heroSearchTerm.trim().toLowerCase();
    if (!search) return true;

    return (
      project.projectNumber.toLowerCase().includes(search) ||
      project.title.toLowerCase().includes(search) ||
      project.customer.toLowerCase().includes(search) ||
      project.status.toLowerCase().includes(search) ||
      project.description.toLowerCase().includes(search) ||
      getProjectKind(project).toLowerCase().includes(search)
    );
  });
  const getPipelineStatusCount = (statusLabel: string) => {
    const projectsForKind = selectedProjectKindFilter
      ? selectedProjectKindFilter === "potentials"
        ? activePipelineProjects.filter(hasProjectPotential)
        : activePipelineProjects.filter(
            (project) =>
              normalizeProjectKindValue(getProjectKind(project)) ===
              normalizeProjectKindValue(selectedProjectKindFilter)
          )
      : activePipelineProjects;

    if (statusLabel === "Alle Offenen") {
      return projectsForKind.length;
    }

    return projectsForKind.filter(
      (project) => normalizeProjectPipelineStatus(project.status) === normalizeProjectPipelineStatus(statusLabel)
    ).length;
  };
  const activePipelineStatus =
    projectLifecycleStatuses.find(
      (statusItem) =>
        normalizeProjectPipelineStatus(statusItem.label) === normalizeProjectPipelineStatus(selectedProjectPipelineStatus)
    ) ?? activeProjectPipeline.statuses[1];
  const projectPipelineTitle =
    isRecurringProjectKindValue(selectedProjectKindFilter)
      ? `Dauerläufer-Projekte ${activeProjectPipeline.company}`
      : selectedProjectKindFilter && normalizeProjectKindValue(selectedProjectKindFilter) === ONE_TIME_PROJECT_KIND
        ? `Einmalige-Projekte ${activeProjectPipeline.company}`
        : selectedProjectKindFilter === "potentials"
          ? `Zusatzverkäufe ${activeProjectPipeline.company}`
        : activeProjectPipeline.label;
  const projectPipelineSubline =
    isRecurringProjectKindValue(selectedProjectKindFilter)
      ? "Hier werden Projekte mit längerer Laufzeit gemanagt"
      : selectedProjectKindFilter && normalizeProjectKindValue(selectedProjectKindFilter) === ONE_TIME_PROJECT_KIND
        ? "Hier werden einmalige Projekte gemanagt"
        : selectedProjectKindFilter === "potentials"
          ? "Hier landen Zusatzverkäufe, bei denen der Kunde aktuell kein Angebot wünscht."
        : `Getrennte Pipeline für ${activeProjectPipeline.company} mit eigenen Status.`;

  async function updateSelectedProjectStatus(nextStatus: string) {
    if (!selectedProjectFileId) return;

    const currentProject = heroProjects.find((project) => project.id === selectedProjectFileId);
    if (!currentProject) return;

    const updatedProject = { ...currentProject, status: nextStatus };
    try {
      await persistProject(updatedProject);
    } catch (error) {
      setErrorMessage(error instanceof Error ? error.message : "Projektstatus konnte nicht gespeichert werden.");
      return;
    }

    setHeroProjects((currentProjects) =>
      currentProjects.map((project) =>
        project.id === selectedProjectFileId ? { ...project, status: nextStatus } : project
      )
    );
    await addProjectLogbookEntry(
      currentProject.id,
      "Projektstatus",
      `Projektstatus geändert: ${currentProject.status || "-"} -> ${nextStatus}.`
    );
    setSelectedProjectPipelineStatus(nextStatus);
    setSelectedHeroDetailId(selectedProjectFileId);
    setIsProjectStatusMenuOpen(false);
  }

  function openProjectTaskModal(project: HeroProjectPreview, mode: "task" | "appointment") {
    const plannedDate = project.projectRuntimeFrom || formatDateKey(new Date());
    const defaultDeadline = `${plannedDate}T12:00`;

    setIsQuickCreateOpen(false);
    setEditingTask(null);
    setErrorMessage("");
    resetForm();
    setTitel(mode === "appointment" ? `Termin: ${project.title}` : project.title);
    setBeschreibung(
      [
        `${project.projectNumber || project.id} | ${project.title}`,
        project.description,
        project.address ? `Projektanschrift: ${project.address}` : "",
      ]
        .filter(Boolean)
        .join("\n")
    );
    setKunde(project.customer || "");
    setSelectedHeroProjectId(project.id);
    setFaelligkeit(defaultDeadline);

    if (mode === "appointment") {
      setActiveTab("planningBoard");
      setVorgabeMinuten("60");
      setPlanningEnabled(true);
      setPlanningAllocations([{ date: plannedDate, minutes: 60 }]);
    }

    if (!hasLoadedHeroProjects) void loadHeroProjects();
    setIsModalOpen(true);
    setSelectedCalendarActionDate("");
  }

  function openProjectPlanningBoard(options: { date?: string; groupName?: string } = {}) {
    setIsProjectPlanningDayOverlayOpen(false);
    setSelectedProjectFileId("");
    setProjectFileTab("logbook");
    setPlanningOwnerFilter(activeUserId || "");
    if (/^\d{4}-\d{2}-\d{2}$/.test(options.date ?? "")) {
      setSelectedPlanningDateKey(options.date ?? "");
      setPlanningBoardStartDate(options.date ?? "");
      setIsPlanningDayOpen(true);
    } else {
      setIsPlanningDayOpen(false);
    }
    if (options.groupName) {
      setSelectedPlanningGroup(options.groupName);
    }
    setPlanningBoardView("board");
    setActiveTab("planningBoard");
  }

  function openProjectPlanningDayOverlay(options: { date: string; groupName?: string }) {
    setSelectedPlanningDateKey(options.date);
    setPlanningBoardStartDate(options.date);
    if (options.groupName) {
      setSelectedPlanningGroup(options.groupName);
    }
    setPlanningBoardView("board");
    setIsProjectPlanningDayOverlayOpen(true);
  }

  function printProjectOverview(project: HeroProjectPreview, address: string) {
    const printWindow = window.open("", "_blank", "width=900,height=700");

    if (!printWindow) {
      setErrorMessage("Projektübersicht konnte nicht geöffnet werden.");
      return;
    }

    const fields = [
      ["Projektnummer", project.projectNumber || project.id],
      ["Projektname", project.title],
      ["Kunde", project.customer || "-"],
      ["Projektverantwortlicher", project.responsibleName || activeUser?.name || "-"],
      ["Projektanschrift", address || "-"],
      ["Projektstatus", project.status || "-"],
      ["Projektstart", project.projectRuntimeFrom || "-"],
      ["Projektlaufzeit bis", project.projectRuntimeUntil || "-"],
      ["Fakturierungsintervall", project.billingInterval || "-"],
      ["Gewerk", project.trade || "-"],
      ["Niederlassung", project.branch || "-"],
      ["Quelle", project.source || "-"],
      ["Projektvolumen", project.volume || "-"],
      ["Projektzeitkontingent", project.timeBudgetHours || "-"],
      ["Erstellungsdatum", project.createdAt || "-"],
    ];

    printWindow.document.write(`
      <!doctype html>
      <html>
        <head>
          <title>Projektübersicht ${project.projectNumber || project.id}</title>
          <style>
            body { color: #0f172a; font-family: Arial, sans-serif; margin: 32px; }
            h1 { font-size: 24px; margin: 0 0 6px; }
            p { color: #475569; margin: 0 0 24px; }
            dl { display: grid; grid-template-columns: 210px 1fr; gap: 0; max-width: 760px; }
            dt, dd { border-bottom: 1px solid #d8e0ea; margin: 0; padding: 9px 0; }
            dt { font-weight: 700; }
            dd { color: #005fff; font-weight: 650; overflow-wrap: anywhere; }
          </style>
        </head>
        <body>
          <h1>${project.projectNumber || project.id} | ${project.title}</h1>
          <p>${project.customer || "Kunde noch nicht gesetzt"}</p>
          <dl>
            ${fields
              .map(
                ([label, value]) =>
                  `<dt>${label}</dt><dd>${String(value)
                    .replaceAll("&", "&amp;")
                    .replaceAll("<", "&lt;")
                    .replaceAll(">", "&gt;")}</dd>`
              )
              .join("")}
          </dl>
        </body>
      </html>
    `);
    printWindow.document.close();
    printWindow.focus();
    printWindow.print();
  }

  function printPdfDocument(url: string) {
    const printWindow = window.open(url, "_blank");

    if (!printWindow) {
      setErrorMessage("PDF konnte nicht zum Drucken geöffnet werden.");
      return;
    }

    window.setTimeout(() => {
      try {
        printWindow.focus();
        printWindow.print();
      } catch {
        setErrorMessage("PDF wurde geöffnet. Bitte den Druckdialog im Browser starten.");
      }
    }, 700);
  }

  async function printInvoiceDocument(invoice: InvoiceItem) {
    printPdfDocument(getInvoicePdfUrl(invoice.id));

    const res = await fetch("/api/invoices", {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        id: invoice.id,
        action: "mark-printed",
        actorId: activeUserId,
      }),
    });

    if (!res.ok) {
      const data = await res.json().catch(() => null);
      setErrorMessage(data?.error ?? "Druck konnte nicht in der Rechnungshistorie markiert werden.");
      return;
    }

    if (invoice.projectId) {
      await loadInvoiceHistory(invoice.projectId);
      await addProjectLogbookEntry(
        invoice.projectId,
        "Rechnung",
        `Rechnung ${getInvoiceDisplayNumber(invoice)} wurde zum Drucken geöffnet.`
      );
    }
  }

  const selectedProjectContact = contacts.find((contact) => contact.id === projectDraft.contactId);
  const selectedProjectCompany =
    selectedProjectContact && selectedProjectContact.type === "company"
      ? selectedProjectContact
      : selectedProjectContact
        ? getCustomerFileTarget(selectedProjectContact)
        : null;
  const projectContactPersons = selectedProjectCompany
    ? contacts
        .filter(
          (contact) =>
            contact.category === "Ansprechpartner" &&
            (contact.parentCompanyId === selectedProjectCompany.id ||
              (selectedProjectCompany.companyName &&
                contact.parentCompanyName === selectedProjectCompany.companyName))
        )
        .sort((first, second) => {
          if (first.isMainContact && !second.isMainContact) return -1;
          if (!first.isMainContact && second.isMainContact) return 1;
          return getContactDisplayName(first).localeCompare(getContactDisplayName(second), "de");
        })
    : [];
  const projectAddressOptions = selectedProjectCompany
    ? [
        selectedProjectCompany,
        ...contacts.filter(
          (contact) =>
            contact.id !== selectedProjectCompany.id &&
            (contact.parentCompanyId === selectedProjectCompany.id ||
              (selectedProjectCompany.companyName &&
                contact.parentCompanyName === selectedProjectCompany.companyName))
        ),
      ]
    : [];
  const selectedProjectContactPotentials = selectedProjectCompany
    ? projectPotentials.filter(
        (potential) =>
          ["open", "follow_up"].includes(potential.status) &&
          (potential.contactId === selectedProjectCompany.id ||
            (!!selectedProjectCompany.companyName &&
              potential.customerName.trim().toLowerCase() === selectedProjectCompany.companyName.trim().toLowerCase()))
      )
    : [];
  const contactCompanyOptions = contacts
    .filter((contact) => contact.type === "company")
    .sort((first, second) => getContactDisplayName(first).localeCompare(getContactDisplayName(second), "de"));
  const projectContactPickerOptions = contacts
    .filter((contact) => {
      const search = projectContactPickerSearch.trim().toLowerCase();
      if (!search) return true;

      return [
        getContactLabel(contact),
        getContactAddressLine(contact),
        contact.customerNumber,
        contact.email,
      ]
        .filter(Boolean)
        .some((value) => value.toLowerCase().includes(search));
    })
    .slice(0, 8);
  function selectProjectContact(contact: ContactItem) {
    const projectContact = contact.type === "person" ? getCustomerFileTarget(contact) : contact;

    setProjectDraft((currentDraft) => ({
      ...currentDraft,
      contactId: projectContact.id,
      contactPersonId: contact.type === "person" ? contact.id : "",
      addressContactId: "",
    }));
    setIsProjectContactPickerOpen(false);
    setProjectContactPickerSearch("");
  }
  const normalizeStampSearchValue = (value: string) =>
    value
      .normalize("NFD")
      .replace(/[\u0300-\u036f]/g, "")
      .toLowerCase();
  const getStampProjectFilterKey = (entry: StampTimeEntry) => {
    if (entry.mode === "unproductive") return "__unproductive__";
    return entry.projectId || entry.projectLabel || "";
  };
  const getStampProjectFilterLabel = (entry: StampTimeEntry) => {
    if (entry.mode === "unproductive") return entry.projectLabel || "Unproduktiv";
    const project = entry.projectId ? heroProjects.find((item) => item.id === entry.projectId) : undefined;
    if (project) {
      return [project.projectNumber, project.customer].filter(Boolean).join(" | ") || project.title;
    }
    return entry.projectLabel || "Projekt ohne Bezeichnung";
  };
  const filterStampEntriesForSearch = (entries: StampTimeEntry[], projectFilter: string, searchValue: string) => {
    const normalizedProjectFilter = normalizeStampSearchValue(projectFilter.trim());
    const normalizedSearch = normalizeStampSearchValue(searchValue.trim());
    return entries.filter((entry) => {
      const project = entry.projectId ? heroProjects.find((item) => item.id === entry.projectId) : undefined;
      if (normalizedProjectFilter) {
        const projectHaystack = [
          getStampProjectFilterLabel(entry),
          getStampProjectFilterKey(entry),
          entry.projectLabel,
          entry.mode === "project" ? "Produktiv" : "Unproduktiv",
          project?.projectNumber,
          project?.title,
          project?.customer,
        ];
        const matchesProject = projectHaystack
          .filter(Boolean)
          .some((value) => normalizeStampSearchValue(String(value)).includes(normalizedProjectFilter));
        if (!matchesProject) return false;
      }
      if (!normalizedSearch) return true;

      return [
        entry.date,
        entry.startTime,
        entry.endTime,
        entry.mode === "project" ? "Produktiv" : "Unproduktiv",
        entry.entrySource === "manual" ? "Manuell" : "Gestempelt",
        entry.projectLabel,
        project?.projectNumber,
        project?.title,
        project?.customer,
        entry.employee,
        entry.comment,
        entry.invoiceNumber,
      ]
        .filter(Boolean)
        .some((value) => normalizeStampSearchValue(String(value)).includes(normalizedSearch));
    });
  };
  const openStampProjects = heroProjects.filter(
    (project) => project.status !== "Abgeschlossen" && project.status !== "Archiviert"
  );
  const stampProjectSearchTerm = normalizeStampSearchValue(stampProjectSearch.trim());
  const stampProjectOptions = openStampProjects
    .filter((project) => {
      if (!stampProjectSearchTerm) return true;
      return [
        project.projectNumber,
        project.title,
        project.customer,
      ]
        .filter(Boolean)
        .some((value) => normalizeStampSearchValue(value).includes(stampProjectSearchTerm));
    })
    .slice(0, 10);
  const selectedStampProject = heroProjects.find((project) => project.id === stampProjectId);
  const currentStampProject =
    stampSession?.mode === "project"
      ? heroProjects.find((project) => String(project.id) === String(stampSession.projectId))
      : null;
  const isCurrentStampProjectImmocare =
    Boolean(currentStampProject) && getProjectCompany(currentStampProject) === "OK immocare";
  const shouldShowFinalInspectionChecklist =
    stampCompletionState === "finished" &&
    stampSession?.mode === "project" &&
    (isCurrentStampProjectImmocare || finalInspectionOptionalOpen);
  const stampNeedsCompletionDecision =
    stampModalMode === "change" && stampSession?.mode === "project" && !stampCompletionState;
  const stampCanChooseFollowUp = stampModalMode !== "stop" && !stampNeedsCompletionDecision;
  const todayStampDate = new Intl.DateTimeFormat(APP_LOCALE, {
    day: "2-digit",
    month: "2-digit",
    year: "numeric",
    timeZone: APP_TIME_ZONE,
  }).format(new Date(timerNow));
  const completedTodayStampMilliseconds = stampEntries
    .filter((entry) => {
      if (entry.date !== todayStampDate) return false;
      if (!activeUser?.name) return true;
      return entry.employee === activeUser.name;
    })
    .reduce((sum, entry) => sum + entry.durationMs, 0);
  const kanbanStatuses: TaskStatus[] = [
    "offen",
    "in Bearbeitung",
    "wartet auf R\u00fcckmeldung",
    "erledigt",
    "\u00fcberf\u00e4llig",
  ];
  const kanbanTasks = kanbanOwnerFilter
    ? myRelevantTasks.filter(
        (task) =>
          task.zustaendigId === kanbanOwnerFilter ||
          (kanbanOwnerFilter === activeUserId && isTaskEscalatedToActiveUser(task))
      )
    : myRelevantTasks;
  const calendarDays = getMonthDays(calendarDate);
  const calendarVisibleDateKeys = new Set(
    calendarDays.filter((day): day is Date => Boolean(day)).map(formatDateKey)
  );
  const weekDays = getWeekDays(calendarDate);
  const weekVisibleDateKeys = new Set(weekDays.map(formatDateKey));
  const getTaskPlanningEntries = (task: TaskItem) =>
    task.planningAllocations.length > 0
      ? task.planningAllocations
      : [
          {
            date: task.faelligkeit.slice(0, 10),
            minutes: task.vorgabeMinuten ?? 0,
          },
        ];
  const getTaskPlannedMinutesForDate = (task: TaskItem, dateKey: string) =>
    getTaskPlanningEntries(task)
      .filter((allocation) => allocation.date === dateKey)
      .reduce((total, allocation) => total + allocation.minutes, 0);
  const planningTasks = myRelevantTasks.filter(
    (task) =>
      task.status !== "erledigt" &&
      (!effectivePlanningOwnerFilter ||
        task.zustaendigId === effectivePlanningOwnerFilter ||
        (effectivePlanningOwnerFilter === activeUserId && isTaskEscalatedToActiveUser(task)))
  );
  const tasksByDate = planningTasks.reduce<Record<string, TaskItem[]>>((groupedTasks, task) => {
    if (!task.faelligkeit) return groupedTasks;

    getTaskPlanningEntries(task).forEach((allocation) => {
      groupedTasks[allocation.date] = [...(groupedTasks[allocation.date] ?? []), task];
    });
    return groupedTasks;
  }, {});
  const planningAbsences = absences.filter(
    (absence) => !effectivePlanningOwnerFilter || absence.userId === effectivePlanningOwnerFilter
  );
  const absencesByDate = planningAbsences.reduce<Record<string, AbsenceItem[]>>(
    (groupedAbsences, absence) => {
      groupedAbsences[absence.date] = [...(groupedAbsences[absence.date] ?? []), absence];
      return groupedAbsences;
    },
    {}
  );
  const holidaysByDate = holidays.reduce<Record<string, HolidayItem>>((groupedHolidays, holiday) => {
    groupedHolidays[holiday.date] = holiday;
    return groupedHolidays;
  }, {});
  const getHolidayForDateKey = (dateKey: string) => holidaysByDate[dateKey];
  const isWeekendDateKey = (dateKey: string) => {
    const day = new Date(`${dateKey}T12:00`).getDay();
    return day === 0 || day === 6;
  };
  const planningBoardDays = Array.from({ length: 29 }, (_, index) => {
    const date = new Date(`${planningBoardStartDate}T12:00`);
    date.setHours(12, 0, 0, 0);
    date.setDate(date.getDate() + index);
    return date;
  });
  const planningBoardEndDate = planningBoardDays[planningBoardDays.length - 1] ?? new Date(`${planningBoardStartDate}T12:00`);
  const planningBoardRangeLabel = `${formatProjectDate(planningBoardStartDate)} - ${formatProjectDate(formatDateKey(planningBoardEndDate))}`;
  const shiftPlanningBoardStart = (days: number) => {
    setPlanningBoardStartDate((currentStart) => addDaysToDateKey(currentStart, days));
  };
  const getPlanningBoardUsers = (company: string, groupName: string) =>
    users.filter((user) => {
      if (!user.isActive) return false;
      if ((user.planningBoard ?? "OK solutions") !== company) return false;
      return groupName === "Gesamt" || (user.planningGroup ?? "") === groupName;
    });
  const getWeeklyDayKeyForDate = (dateKey: string): WeeklyDayKey => {
    const day = new Date(`${dateKey}T12:00`).getDay();
    return weeklyCapacityDayLabels[(day + 6) % 7].key;
  };
  const getUserCapacityForDate = (user: UserOption, dateKey: string) => {
    if (isWeekendDateKey(dateKey)) return 0;
    if (getHolidayForDateKey(dateKey)) return 0;
    const absence = getUserAbsenceForDateKey(user.id, dateKey);
    const capacity = getSafeWeeklyCapacity(user.weeklyCapacity);
    const baseCapacity = capacity[getWeeklyDayKeyForDate(dateKey)] ?? 0;
    return absence ? (absence.dayPart === "full" ? 0 : baseCapacity / 2) : baseCapacity;
  };
  const getUserPlanningWindowForDate = (user: UserOption | undefined, dateKey: string) => {
    const dayKey = getWeeklyDayKeyForDate(dateKey);
    const windows = getSafePlanningTimeWindows(
      user?.planningTimeWindows,
      user?.planningStartTime ?? "08:00",
      user?.planningEndTime ?? "17:00"
    );
    return windows[dayKey];
  };
  const getUserBreakWindowForDate = (user: UserOption | undefined, dateKey: string) => {
    const dayKey = getWeeklyDayKeyForDate(dateKey);
    const windows = getSafePlanningTimeWindows(user?.planningBreakWindows, "", "");
    return windows[dayKey];
  };
  const getPlanningBoardCapacity = (company: string, groupName: string, dateKey: string) =>
    getPlanningBoardUsers(company, groupName).reduce(
      (total, user) => total + getUserCapacityForDate(user, dateKey),
      0
    );
  const getPlanningEntriesForScope = (company: string, groupName: string, dateKey: string) =>
    planningEntries.filter((entry) => {
      if (entry.deletedAt) return false;
      if (entry.date !== dateKey) return false;
      if (entry.board !== company) return false;
      if (groupName === "Gesamt") return true;
      return entry.groupName === groupName;
    });
  const getPlanningPlannedHours = (company: string, groupName: string, dateKey: string) =>
    getPlanningEntriesForScope(company, groupName, dateKey).reduce(
      (total, entry) => total + entry.durationMinutes / 60,
      0
    );
  const getPlanningBoardUtilization = (company: string, groupName: string, dateKey: string) => {
    const capacityHours = getPlanningBoardCapacity(company, groupName, dateKey);
    const plannedHours = getPlanningPlannedHours(company, groupName, dateKey);
    const percent = capacityHours > 0 ? Math.round((plannedHours / capacityHours) * 100) : 0;

    return {
      capacityHours,
      plannedHours,
      percent,
    };
  };
  const getEmployeePlannedHours = (employeeName: string, groupName: string, dateKey: string) =>
    planningEntries
      .filter(
        (entry) =>
          !entry.deletedAt &&
          entry.date === dateKey &&
          entry.groupName === groupName &&
          entry.employeeName === employeeName
      )
      .reduce((total, entry) => total + entry.durationMinutes / 60, 0);
  const getEmployeePlanningUtilization = (
    employeeName: string,
    capacityHours: number,
    groupName: string,
    dateKey: string
  ) => {
    const plannedHours = getEmployeePlannedHours(employeeName, groupName, dateKey);
    const percent = capacityHours > 0 ? Math.round((plannedHours / capacityHours) * 100) : 0;

    return {
      plannedHours,
      percent,
    };
  };
  const selectedPlanningGroupEmployees =
    users
      .filter((user) => user.isActive && (user.planningGroup ?? "") === selectedPlanningGroup)
      .map((user) => user.name);
  const selectedPlanningDate = new Date(`${selectedPlanningDateKey}T12:00`);
  const selectedPlanningHoliday = getHolidayForDateKey(selectedPlanningDateKey);
  const selectedPlanningIsWeekend = isWeekendDateKey(selectedPlanningDateKey);
  const getPlanningSlotIndex = (time: string) => {
    const hour = Number(time.slice(0, 2));
    const minute = Number(time.slice(3, 5));
    return Math.max(0, Math.min(planningSlotColumnCount, (hour - 6) * 4 + minute / 15));
  };
  const getPlanningMinutesBetween = (startTime: string, endTime: string) => {
    const start = Number(startTime.slice(0, 2)) * 60 + Number(startTime.slice(3, 5));
    const end = Number(endTime.slice(0, 2)) * 60 + Number(endTime.slice(3, 5));
    return Math.max(0, end - start);
  };
  const doPlanningTimesOverlap = (
    firstStart: string,
    firstEnd: string,
    secondStart: string,
    secondEnd: string
  ) =>
    Math.max(getPlanningSlotIndex(firstStart), getPlanningSlotIndex(secondStart)) <
    Math.min(getPlanningSlotIndex(firstEnd), getPlanningSlotIndex(secondEnd));
  const isPlanningEntryCreatedAfter = (entry: PlanningEntry, candidate: PlanningEntry) => {
    const entryCreatedAt = parseAppDateTime(entry.createdAt).getTime();
    const candidateCreatedAt = parseAppDateTime(candidate.createdAt).getTime();

    if (!Number.isFinite(entryCreatedAt) || !Number.isFinite(candidateCreatedAt)) return false;
    if (entryCreatedAt === candidateCreatedAt) return entry.id > candidate.id;
    return entryCreatedAt > candidateCreatedAt;
  };
  const getPlanningNetMinutesBetween = (
    startTime: string,
    endTime: string,
    breakWindow?: PlanningTimeWindow
  ) => {
    const grossMinutes = getPlanningMinutesBetween(startTime, endTime);
    if (!breakWindow?.start || !breakWindow.end) return grossMinutes;

    const start = Number(startTime.slice(0, 2)) * 60 + Number(startTime.slice(3, 5));
    const end = Number(endTime.slice(0, 2)) * 60 + Number(endTime.slice(3, 5));
    const breakStart =
      Number(breakWindow.start.slice(0, 2)) * 60 + Number(breakWindow.start.slice(3, 5));
    const breakEnd =
      Number(breakWindow.end.slice(0, 2)) * 60 + Number(breakWindow.end.slice(3, 5));
    const overlap = Math.max(0, Math.min(end, breakEnd) - Math.max(start, breakStart));

    return Math.max(0, grossMinutes - overlap);
  };
