              <label>Einheit<select value={catalogDraft.unit} onChange={(event) => updateCatalogDraft("unit", event.target.value)}>{getUnitOptions(catalogDraft.unit).map((unit) => <option key={unit} value={unit}>{unit}</option>)}</select></label>
